#import <Cocoa/Cocoa.h>
int main(int argc,char **argv){@autoreleasepool{NSString *dir=[NSString stringWithUTF8String:argv[1]];for(NSNumber *n in @[@16,@32,@128,@256,@512]){for(int retina=1;retina<=2;retina++){int size=n.intValue*retina;NSImage *im=[[NSImage alloc]initWithSize:NSMakeSize(size,size)];[im lockFocus];[[NSColor colorWithRed:.10 green:.13 blue:.10 alpha:1]setFill];[[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(0,0,size,size) xRadius:size*.22 yRadius:size*.22]fill];[[NSColor colorWithRed:.84 green:.93 blue:.51 alpha:1]setFill];[[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(size*.18,size*.18,size*.64,size*.64) xRadius:size*.12 yRadius:size*.12]fill];NSDictionary *attrs=@{NSFontAttributeName:[NSFont systemFontOfSize:size*.53 weight:NSFontWeightHeavy],NSForegroundColorAttributeName:[NSColor colorWithRed:.10 green:.15 blue:.08 alpha:1]};NSSize text=[@"S" sizeWithAttributes:attrs];[@"S" drawAtPoint:NSMakePoint((size-text.width)/2,(size-text.height)/2) withAttributes:attrs];[im unlockFocus];NSBitmapImageRep *rep=[NSBitmapImageRep imageRepWithData:im.TIFFRepresentation];NSString *name=[NSString stringWithFormat:@"icon_%@x%@%@.png",n,n,retina==2?@"@2x":@""];[[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:[dir stringByAppendingPathComponent:name] atomically:YES];}}}return 0;}
